// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.lang.reflect.Field;
import java.util.List;
import java.util.concurrent.atomic.LongAdder;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.io.TempDir;

/**
 * Spike (Routine C): determines WHEN the hot-path adjacency/CSF counters actually run.
 * <p>
 * For each query shape the counters are sampled around three phases that a user can trigger independently: plain
 * evaluation, {@code explain(Optimized)} and {@code explain(Telemetry)}. If a counter only existed to serve query
 * explanation it would move only in the explain phases; anything that moves during plain evaluation is unconditional
 * instrumentation on the query hot path.
 * <p>
 * Diagnostic only - this test asserts the minimum needed to keep itself honest and prints a table.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class TelemetryActivationSpikeTest {

	private static final String NS = "http://example.com/telemetryspike/";
	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final int PEOPLE = 2000;
	private static final int COMPANIES = 40;
	private static final String PREFIX = "PREFIX ex: <" + NS + ">\n";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private LmdbSailStore backing;
	private LmdbDirectAdjacencyStore direct;
	private LongAdder csfDecodes;

	private record Scenario(String name, String query) {
	}

	private final List<Scenario> scenarios = List.of(
			new Scenario("lookup_out(s bound)", PREFIX + "SELECT ?o WHERE { ex:person42 ex:knows ?o }"),
			new Scenario("full_predicate_scan", PREFIX + "SELECT ?s ?o WHERE { ?s ex:knows ?o }"),
			new Scenario("two_hop_from_seed",
					PREFIX + "SELECT ?o WHERE { ex:person42 ex:knows ?m . ?m ex:knows ?o }"),
			new Scenario("chain_join_open",
					PREFIX + "SELECT ?p ?city WHERE { ?p ex:worksAt ?c . ?c ex:locatedIn ?city }"),
			new Scenario("object_object_join",
					PREFIX + "SELECT ?a ?b WHERE { ?a ex:worksAt ?c . ?b ex:worksAt ?c }"),
			new Scenario("triangle_wcoj",
					PREFIX + "SELECT ?a ?b ?c WHERE { ?a ex:knows ?b . ?b ex:knows ?c . ?a ex:knows ?c }"));

	@BeforeAll
	void setUp() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore sail = new LmdbStore(dataDir, config);
		repository = new SailRepository(sail);
		repository.init();
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			for (int i = 0; i < PEOPLE; i++) {
				IRI person = person(i);
				for (int neighbor : neighborsOf(i)) {
					conn.add(person, iri("knows"), person(neighbor));
				}
				conn.add(person, iri("age"), F.createLiteral(18 + (i % 60)));
				conn.add(person, iri("worksAt"), company(i % COMPANIES));
			}
			for (int c = 0; c < COMPANIES; c++) {
				conn.add(company(c), iri("locatedIn"), city(c % 10));
			}
			conn.commit();
		}
		backing = sail.getBackingStore();
		direct = backing.directAdjacencyStore();
		assertTrue(direct != null && direct.buildNowForTest(), "direct adjacency build must complete");

		Field field = Class.forName("org.eclipse.rdf4j.sail.lmdb.csf.CompactCsfPageReader")
				.getDeclaredField("DECODES");
		field.setAccessible(true);
		csfDecodes = (LongAdder) field.get(null);
	}

	@AfterAll
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	void whenDoTheHotPathCountersActuallyRun() {
		System.out.printf("%n%-24s %-18s %8s %9s %9s %11s %11s%n",
				"scenario", "phase", "rows", "adjHits", "adjMisses", "kernelViews", "csfDecodes");
		for (Scenario scenario : scenarios) {
			// warm: one-time plan compilation and cache fills must not land in a measured phase
			evaluate(scenario.query());

			Sample before = sample();
			long rows = evaluate(scenario.query());
			report(scenario.name(), "evaluate", rows, before.delta(sample()));

			before = sample();
			explain(scenario.query(), Explanation.Level.Optimized);
			report(scenario.name(), "explain(Optimized)", 0, before.delta(sample()));

			before = sample();
			explain(scenario.query(), Explanation.Level.Telemetry);
			report(scenario.name(), "explain(Telemetry)", 0, before.delta(sample()));
		}
	}

	private record Sample(long hits, long misses, long kernelViews, long decodes) {

		long[] delta(Sample after) {
			return new long[] { after.hits - hits, after.misses - misses, after.kernelViews - kernelViews,
					after.decodes - decodes };
		}
	}

	private Sample sample() {
		LmdbAdjacencyMetrics.Snapshot snapshot = direct.snapshotMetrics();
		return new Sample(snapshot.lookupHits, snapshot.exactMisses,
				LmdbDirectAdjacencyStore.KERNEL_VIEWS_SERVED.get(), csfDecodes.sum());
	}

	private static void report(String scenario, String phase, long rows, long[] delta) {
		System.out.printf("%-24s %-18s %8d %9d %9d %11d %11d%n", scenario, phase, rows, delta[0], delta[1], delta[2],
				delta[3]);
	}

	private long evaluate(String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(query).evaluate()) {
			long rows = 0;
			while (result.hasNext()) {
				result.next();
				rows++;
			}
			return rows;
		}
	}

	private void explain(String query, Explanation.Level level) {
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.prepareTupleQuery(query).explain(level).toString();
		}
	}

	private static int[] neighborsOf(int i) {
		int a = (i + 1) % PEOPLE;
		int b = (i + 2) % PEOPLE;
		int c = (i * 31 + 7) % PEOPLE;
		if (c == i || c == a || c == b) {
			c = (i + 3) % PEOPLE;
		}
		return new int[] { a, b, c };
	}

	private static IRI iri(String local) {
		return F.createIRI(NS, local);
	}

	private static IRI person(int i) {
		return F.createIRI(NS, "person" + i);
	}

	private static IRI company(int i) {
		return F.createIRI(NS, "company" + i);
	}

	private static IRI city(int i) {
		return F.createIRI(NS, "city" + i);
	}
}
